package com.spaceagent.platform.artifact.application;import com.spaceagent.platform.artifact.api.ArtifactApplicationApi;import com.spaceagent.platform.artifact.domain.*;import com.spaceagent.shared.id.IdGenerator;import com.spaceagent.shared.time.TimeProvider;import org.springframework.stereotype.Service;import java.util.List;import java.util.Optional;
@Service public class ArtifactApplicationService implements ArtifactApplicationApi{private final ArtifactRepository repo;private final IdGenerator ids;private final TimeProvider time;public ArtifactApplicationService(ArtifactRepository r,IdGenerator i,TimeProvider t){repo=r;ids=i;time=t;}public ArtifactView create(CreateCommand c){Artifact a=new Artifact(ids.nextId(),c.tenantId(),c.projectId(),c.taskId(),c.agentRunId(),c.workspaceId(),c.type(),c.name(),c.contentRef(),c.contentHash(),c.summary(),c.metadataJson(),time.now());repo.save(a);return view(a);}public Optional<ArtifactView> find(String tenantId,String id){return repo.findById(id).filter(a->a.tenantId().equals(tenantId)).map(ArtifactApplicationService::view);}public List<ArtifactView> byRun(String id){return repo.findByRunId(id).stream().map(ArtifactApplicationService::view).toList();}public List<ArtifactView> byTask(String id){return repo.findByTaskId(id).stream().map(ArtifactApplicationService::view).toList();}private static ArtifactView view(Artifact a){return new ArtifactView(a.id(),a.projectId(),a.taskId(),a.agentRunId(),a.workspaceId(),a.type(),a.name(),a.contentRef(),a.contentHash(),a.summary(),a.metadataJson(),a.createdAt());}}
